                if g[r][c] == 'B':
                    run = 0
                    cc = c
                    while cc < 64 and g[r][cc] == 'B':
                        run += 1
                        cc += 1
                    if run >= 6 and r + 1 < 64 and 'Y' in g[r + 1][c:c + 15]:
                        return (r, c)
        return (45, 35)

    sr, sc = find_sprite(grid)

