    cur = 0
    for c in range(64):
        if grid[0][c] == 'w':
            cur = c
            break

    if action == "RIGHT":
        sc += 1
        cur = (cur + 1) % 64
    elif action == "LEFT":
        sc -= 1
        cur = (cur + 1) % 64
    elif action == "UP":
        sr -= 1
        cur = (cur + 1) % 64
    elif action == "DOWN":
        sr += 1
        cur = (cur + 1) % 64
    elif action.startswith("MOUSE"):
