def predict(board_lines, action):
    b = [list(r) for r in board_lines]
    H = 64; W = 64

    # Flood the connected region of the "empty" color reachable from the
    # pressed edge, converting it to 'p' and turning adjacent block tiles
    # into wall 'c'. We approximate: convert every 'b' reachable from the
    # edge to 'p', and any non-empty tile on the frontier to 'c'.
    def flood(edge):
        # seed cells on the pressed edge
        seeds = []
        if edge == 'L':
            seeds = [(r, 0) for r in range(H)]
        elif edge == 'R':
            seeds = [(r, W-1) for r in range(H)]
        elif edge == 'U':
            seeds = [(0, c) for c in range(W)]
        elif edge == 'D':
            seeds = [(H-1, c) for c in range(W)]

        # We flood 'b' (off-map) into 'p' (active).
        from collections import deque
        q = deque()
        visited = [[False]*W for _ in range(H)]
        for (r, c) in seeds:
            if b[r][c] == 'b':
                q.append((r, c)); visited[r][c] = True
        dirs = [(-1,0),(1,0),(0,-1),(0,1)]
        while q:
            r, c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r+dr, c+dc
                if 0 <= nr < H and 0 <= nc < W and not visited[nr][nc]:
                    if b[nr][nc] == 'b':
                        visited[nr][nc] = True
                        q.append((nr, nc))
        # apply: flooded 'b' -> 'p'
        for r in range(H):
            for c in range(W):
                if visited[r][c]:
                    b[r][c] = 'p'
        # frontier block tiles (non b/p/c adjacent to newly-p) -> 'c'
        for r in range(H):
            for c in range(W):
                if visited[r][c]:
                    for dr, dc in dirs:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if b[nr][nc] not in ('b','p','c'):
                                b[nr][nc] = 'c'
        return b

    if action in ('LEFT','RIGHT','UP','DOWN'):
        edge = {'LEFT':'L','RIGHT':'R','UP':'U','DOWN':'D'}[action]
        flood(edge)
        return [''.join(r) for r in b]

    # MOUSE / SPACE / UNDO: cannot reconstruct exactly; no change.
    return [''.join(r) for r in b]

