import re

# --- fixed banners ---------------------------------------------------------
def paint_banners(b, step):
    if step < 1:
        return
    # top-left red banner, rows 6-26, cols 12-17
    for r in range(6, 27):
        for c in range(12, 18):
            b[r][c] = 'G' if r == 6 else 'R'
    # top-right purple banner, rows 6-26, cols 39-41
    for r in range(6, 27):
        for c in range(39, 42):
            b[r][c] = 'p'

# --- left "water" tile rows 6-8, cols 21-35 --------------------------------
def paint_water(b, step):
    if step == 0:
        for r in range(6, 9):
            for c in range(21, 36):
                b[r][c] = 'B'
        return
    for r in range(6, 9):
        for c in range(21, 36):
            b[r][c] = 'S'
    if step == 1:
        b[6][22] = 'r'
    else:
        rr = 20 + step
        if 21 <= rr <= 35:
            b[7][rr] = 'r'

