    "GbbbbbGbb",
    "GrrrbbGbb",
    "GbbbbbGbb",
    "GbbbbbGbb",
    "GbbbbbGbb",
    "GbbbbbGbb",
    "GbbbbbGbb",
    "GbbbbbGbb",
    "GbbbbbGbb",
]
def paint_rain(b, step):
    if step == 0:
        for r in range(6, 9):
            for c in range(42, 51):
                b[r][c] = 'B'
        return
    s = step % 9
    for i in range(3):
        for j in range(9):
            b[6 + i][42 + j] = PATTERNS[(s + i) % 9][j]

# --- left "box" tile rows 12-20, cols 42-50 (9x9) ---------------------------
