    "OObGNNbG",
    "OrbGNNbG",
    "GbbGNNbG",
    "bbbbbGGG",
    "bbbbbGGG",
    "bbbbbGGG",
    "OObGNNbG",
    "OrbGNNbG",
    "GbbGNNbG",
]
def paint_box(b, step):
    if step == 0:
        for r in range(12, 21):
            for c in range(42, 51):
                b[r][c] = 'B'
        return
    s = step % 9
    for i in range(9):
        row = BOX_PATTERNS[(s + i) % 9]
        for j in range(9):
