def is_interactive(r, c):
    if 48 <= r <= 52 and 8 <= c <= 20:
        return True
    if 48 <= r <= 52 and 52 <= c <= 63:
        return True
    if 58 <= r <= 59 and 15 <= c <= 63:
        return True
    return False

def predict(board_lines, action):
    b = [list(line) for line in board_lines]
    m = re.match(r'MOUSE\((\d+),(\d+)\)', action)
    if m:
        r, c = int(m.group(1)), int(m.group(2))
        if is_interactive(r, c):
            # advance step by 1 (we don't track state, so we infer step from
            # the progress strip: count of 'c' cells in row 63 from the right)
            step = 0
            for cc in range(63, -1, -1):
                if b[63][cc] == 'c':
                    step += 1
                else:
                    break
            step += 1
            # reset the dynamic regions to black before painting
            for r_ in range(6, 9):
                for c_ in list(range(21, 36)) + list(range(42, 51)):
                    b[r_][c_] = 'B'
            for r_ in range(12, 21):
                for c_ in range(42, 51):
                    b[r_][c_] = 'B'
            paint_banners(b, step)
            paint_water(b, step)
            paint_rain(b, step)
            paint_box(b, step)
            paint_progress(b, step)
    return [''.join(row) for row in b]
