            box.append([b[i][j] for j in range(26, 38)])
        for i in range(25, 32):
            for j in range(26, 38):
                b[i][j] = 'B'
        for i in range(25, 32):
            for j in range(26, 38):
                nj = j + direction
                if 0 <= nj < 64:
                    b[i][nj] = box[i][j - 26]

    # 3. SPACE: toggle every cell in cols 27-36 that is currently W or p
    if action == 'SPACE':
        for i in range(64):
            for j in range(27, 37):
                if b[i][j] == 'W':
                    b[i][j] = 'p'
                elif b[i][j] == 'p':
                    b[i][j] = 'W'

    # 4. MOUSE: if target cell is 'G', toggle white square AND window
    if do_mouse is not None:
        mr, mc = do_mouse
        if 0 <= mr < 64 and 0 <= mc < 64 and b[mr][mc] == 'G':
            for i in range(64):
                for j in range(27, 37):
                    if b[i][j] == 'W':
                        b[i][j] = 'p'
                    elif b[i][j] == 'p':
                        b[i][j] = 'W'
            for j in range(35, 46):
                if j == 40:
                    continue
                if b[7][j] == 'W':
                    b[7][j] = 'G'
                elif b[7][j] == 'G':
                    b[7][j] = 'W'

    return [''.join(row) for row in b]
